/**
 * Logo de la boutique, embarqué en base64 pour les documents composés côté
 * serveur : la facture PDF et l'en-tête des e-mails transactionnels.
 *
 * Pourquoi ne pas lire le fichier depuis "public/" : ces documents sont
 * composés dans une fonction serveur, et selon l'hébergeur le dossier "public/"
 * n'est pas garanti présent aux côtés du code (sur Vercel il faut l'ajouter au
 * traçage des fichiers). Embarquer les octets supprime la question, et un logo
 * manquant se verrait immédiatement.
 *
 * Les e-mails, eux, pointent sur l'image hébergée par le site dès que son
 * adresse publique est connue ; sinon l'image est jointe et référencée par
 * "cid:" (cas du développement sans NEXT_PUBLIC_SITE_URL).
 *
 * Source : public/images/logo-icon.png (256 x 256), l'emblème rond
 * « BEST BOX Containerhandel » utilisé aussi dans l'en-tête et le pied du site.
 * Carré, d'où LOGO_RATIO = 1.
 */

/** Identifiant de la pièce jointe référencée par src="cid:…" dans les e-mails. */
export const LOGO_CID = "logo-bbc-best-box-containerhandel";

/** Logo servi par le site, à l'attention des messageries. */
const LOGO_EMAIL_PATH = "/images/logo-icon.png";

/**
 * Adresse du logo pour l'en-tête d'un e-mail : l'URL publique quand on la
 * connaît, sinon l'image jointe. Le mailer n'attache le fichier que si le
 * gabarit a réellement demandé "cid:", il n'y a donc rien d'autre à synchroniser.
 */
export function emailLogoSrc(): string {
  const site = (process.env.NEXT_PUBLIC_SITE_URL ?? "").trim().replace(/\/+$/, "");
  return site ? `${site}${LOGO_EMAIL_PATH}` : `cid:${LOGO_CID}`;
}

